document.addEventListener('DOMContentLoaded',function(){var currentUrl=window.location.href;var encodedUrl=encodeURIComponent(currentUrl);var qrcodeApiUrl='https://api.qrserver.com/v1/create-qr-code/?size=120x120&margin=1&data='+encodedUrl;var qrcodeImg=document.getElementById('qrcode-img');qrcodeImg.src=qrcodeApiUrl;qrcodeImg.onerror=function(){this.src='{$maccms.path_tpl}img/default-qrcode.png';this.alt='二维码加载失败'}});